#include <iostream>
using namespace std;

class FishPond {
public:
    static FishPond& getInstance() {
        static FishPond only;
        return only;
    }
    void add(int n) { total += n; }
    int total = 0;
private:
    FishPond() = default;
};

int main() {
    int n = 0;
    cin >> n;

    FishPond& a = FishPond::getInstance();
    a.add(n);
    FishPond& b = FishPond::getInstance();
    b.add(3);
    cout << "一共 " << a.total << endl;
    cout << "同一只 " << (&a == &b ? "是" : "不是") << endl;
    return 0;
}

